. "$PSScriptRoot\enhancement-ui-common.ps1"
Add-Type @'
using System;using System.Runtime.InteropServices;public static class UxKey{[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr FindWindow(string c,string t);public static IntPtr Window(string t){return FindWindow(null,t);}[DllImport("user32.dll")]public static extern void keybd_event(byte k,byte s,uint f,UIntPtr x);[DllImport("user32.dll")]public static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);[DllImport("user32.dll")]public static extern bool PrintWindow(IntPtr h,IntPtr dc,uint f);}
'@
$exe=Join-Path $Root 'bin\GUNT.ControlCenter.exe';Start-Process $exe -ArgumentList ('"'+$Root+'" overview');Start-Sleep -Seconds 2;$p=Get-Process GUNT.ControlCenter|Select-Object -First 1;$h=$p.MainWindowHandle;$win=[Windows.Automation.AutomationElement]::FromHandle($h)
function Find($parent,$name,$type){$parent.FindFirst([Windows.Automation.TreeScope]::Descendants,(New-Object Windows.Automation.AndCondition((New-Object Windows.Automation.PropertyCondition([Windows.Automation.AutomationElement]::NameProperty,$name)),(New-Object Windows.Automation.PropertyCondition([Windows.Automation.AutomationElement]::ControlTypeProperty,$type)))))}
function Keys([byte]$key,[bool]$control=$false){if($control){[UxKey]::keybd_event(17,0,0,[UIntPtr]::Zero)};[UxKey]::keybd_event($key,0,0,[UIntPtr]::Zero);[UxKey]::keybd_event($key,0,2,[UIntPtr]::Zero);if($control){[UxKey]::keybd_event(17,0,2,[UIntPtr]::Zero)};Start-Sleep -Milliseconds 250}
$win.SetFocus();[GuntEnhanceUi]::SetForegroundWindow($h)|Out-Null;Start-Sleep -Milliseconds 500;Keys 75 $true;Start-Sleep -Milliseconds 700;$dialog=[UxKey]::Window('GUnT_0x9 명령 찾기');if($dialog -eq [IntPtr]::Zero){throw 'Ctrl+K 명령 찾기 없음'};$palette=[Windows.Automation.AutomationElement]::FromHandle($dialog)
$query=Find $palette 'GUNT 명령 검색' ([Windows.Automation.ControlType]::Edit);($query.GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern)).SetValue('Dock');Keys 40;Keys 38;Keys 13;Start-Sleep -Milliseconds 500;if(!(Find $win 'Dock 높이 (DIP)' ([Windows.Automation.ControlType]::Edit)) -and !(Find $win 'Dock 자동 적용 보류' ([Windows.Automation.ControlType]::Text))){throw '명령 검색 Enter 목적지 불일치'}
Keys 75 $true;Keys 27;if([UxKey]::Window('GUnT_0x9 명령 찾기') -ne [IntPtr]::Zero){throw 'Escape 닫기 실패'}
Start-Process $exe -ArgumentList ('"'+$Root+'" monitor');Start-Sleep -Milliseconds 800
$edit=Find $win '모니터 너비 (DIP)' ([Windows.Automation.ControlType]::Edit);$vp=$edit.GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern);$original=$vp.Current.Value;$vp.SetValue(([int]$original+2).ToString())
[UxKey]::PostMessage($h,0x10,[IntPtr]::Zero,[IntPtr]::Zero)|Out-Null;Start-Sleep -Milliseconds 400;$dialog=[UxKey]::Window('미저장 설정');if($dialog -eq [IntPtr]::Zero){throw '창 닫기 보호 없음'};$d=[Windows.Automation.AutomationElement]::FromHandle($dialog);$cancel=Find $d '계속 편집' ([Windows.Automation.ControlType]::Button);($cancel.GetCurrentPattern([Windows.Automation.InvokePattern]::Pattern)).Invoke();Start-Sleep -Milliseconds 200;if($vp.Current.Value -ne ([int]$original+2).ToString()){throw '닫기 취소 시 편집 유실'};$vp.SetValue($original)
$windowPattern=$win.GetCurrentPattern([Windows.Automation.WindowPattern]::Pattern);$transform=$win.GetCurrentPattern([Windows.Automation.TransformPattern]::Pattern);$bounds=$win.Current.BoundingRectangle;$scale=1.75
try{$transform.Resize(780*$scale,560*$scale);Start-Sleep -Milliseconds 500;$apply=Find $win '변경 사항 적용' ([Windows.Automation.ControlType]::Button);$r=$win.Current.BoundingRectangle;$b=$apply.Current.BoundingRectangle;if($b.Bottom -gt $r.Bottom -or $b.Left -lt $r.Left -or $b.Width -le 0){throw '작은 창에서 적용 버튼 접근 불가'}
 $bitmap=New-Object Drawing.Bitmap([int]$r.Width,[int]$r.Height);$g=[Drawing.Graphics]::FromImage($bitmap);$dc=$g.GetHdc();try{[UxKey]::PrintWindow($h,$dc,2)|Out-Null}finally{$g.ReleaseHdc($dc);$g.Dispose()};$bitmap.Save((Join-Path $Root 'screenshots\v25-small-window.png'));$bitmap.Dispose()
}finally{$transform.Resize($bounds.Width,$bounds.Height)}
Write-Json @{Time=(Get-Date).ToString('o');Status='passed';CommandPalette='Ctrl+K 검색·Up/Down·Enter Dock 이동·Escape';DirtyClose='계속 편집 값 유지';SmallWindow='780×560 DIP / 175% 적용 버튼 범위 안';Limitations='100%·150% 물리 화면 미연결. 전역 단축키 등록하지 않음.'} (Join-Path $Root 'logs\v25-keyboard.json')
Start-Process $exe -ArgumentList ('"'+$Root+'" overview')
Write-Output '명령 찾기·닫기 보호·작은 창 175% 검사 통과'
